          mass[MW]}, {0, 1, 1}])/((-1 + \[Xi]w)^2*(-1 + \[Xi]z)*mass[MW]^2*
        (mass[MW] - mass[MZ])^2*(mass[MW] + mass[MZ])^2*
        (mass[MW]^2 - \[Xi]z*mass[MZ]^2)^2) + 
      ((2 - d)*\[Xi]z*sorttad[{0, Sqrt[\[Xi]z]*mass[MZ], mass[MW]}, 
         {0, 1, 1}])/(2*(-1 + \[Xi]w)*(-1 + \[Xi]z)*mass[MW]^2*
        (mass[MW] - mass[MZ])*(mass[MW] + mass[MZ])*(mass[MW]^2 - 
         \[Xi]z*mass[MZ]^2)) + 
      (\[Xi]w*\[Xi]z*sorttad[{0, Sqrt[\[Xi]z]*mass[MZ], 
          Sqrt[\[Xi]w]*mass[MW]}, {0, 1, 1}])/((-1 + \[Xi]w)^2*(-1 + \[Xi]z)*
        mass[MW]^2*(\[Xi]w*mass[MW]^2 - mass[MZ]^2)*(\[Xi]w*mass[MW]^2 - 
         \[Xi]z*mass[MZ]^2)) + (\[Xi]z*sorttad[{0, Sqrt[\[Xi]z]*mass[MZ], 
          mass[MZ]}, {0, 1, 1}])/((-1 + \[Xi]z)^2*(mass[MW] - mass[MZ])^2*
        (mass[MW] + mass[MZ])^2*(\[Xi]w*mass[MW]^2 - mass[MZ]^2)) + 
      (\[Xi]z^2*sorttad[{0, Sqrt[\[Xi]z]*mass[MZ], Sqrt[\[Xi]z]*mass[MZ]}, 
         {0, 1, 1}])/((-1 + \[Xi]z)^2*(-mass[MW]^2 + \[Xi]z*mass[MZ]^2)^2*
        (-(\[Xi]w*mass[MW]^2) + \[Xi]z*mass[MZ]^2))))/
    (1024*cw^4*d*Pi^8*sw^4*mass[MH]^2))
